router.get("/", (req, res) => {
  res.json(db.prepare("SELECT * FROM tasks").all())
})

router.post("/", (req, res) => {
  const result = db.prepare("INSERT INTO tasks (title) VALUES (?)").run(req.body.title)
  res.status(201).json({ id: result.lastInsertRowid })
})

module.exports = router

